public override async Task<UserResponse> GetUser(UserRequest req, ServerCallContext ctx)
{
    using var cts = CancellationTokenSource.CreateLinkedTokenSource(ctx.CancellationToken);
    cts.CancelAfter(ctx.Deadline - DateTime.UtcNow);      // remaining budget, not fresh
    var client = new User.UserClient(_channel);
    return await client.GetUserAsync(req,
        deadline: ctx.Deadline, cancellationToken: cts.Token);
}
